--liquibase formatted sql

-- Prvi prijelaz: prihvati praznu bazu ili tocno poznatu strukturu tablica.
-- Provjerava stupce, tipove, NULL/default/generated, indekse, FK pravila i CHECK izraze.
-- Ne provjerava sadrzaj podataka; dodatne tablice (npr. job_error_log) ostaju sacuvane.
