--changeset eventhub:000-adoption-guard dbms:mariadb
--preconditions onFail:HALT onError:HALT
--precondition-sql-check expectedResult:11 SELECT COUNT(*) FROM (SELECT 'buyer' AS table_name, 'ee84a0bc83b1809996b73a37e9bd174a' AS signature UNION ALL SELECT 'city' AS table_name, 'caaa7dac2452ee1b678cdf550d87ecc9' AS signature UNION ALL SELECT 'event' AS table_name, '77f1a513a7d4cf949b60e9b45739cbfd' AS signature UNION ALL SELECT 'location' AS table_name, '693da63ec14f23af5c0baed031479273' AS signature UNION ALL SELECT 'organizer' AS table_name, '1da4740923451688ebcf9ab715b8c81b' AS signature UNION ALL SELECT 'reservation' AS table_name, '65cf6169137db3bc7d79cec9fddaee89' AS signature UNION ALL SELECT 'reservation_item' AS table_name, '07529f43304d2089fe118a301c345d72' AS signature UNION ALL SELECT 'reservation_seat' AS table_name, '703c65c50188de7338ab45b6d2f93142' AS signature UNION ALL SELECT 'seat' AS table_name, '1c1ac948bdc176e536f67c035ec7d027' AS signature UNION ALL SELECT 'ticket' AS table_name, '5bf27899137c2bb287053bdface392f4' AS signature UNION ALL SELECT 'ticket_category' AS table_name, 'dfcc478fc499bbec7b9b7d9a1f823a02' AS signature) expected LEFT JOIN (SELECT t.TABLE_NAME, MD5(CONCAT_WS('|', t.ENGINE, t.TABLE_COLLATION,  (SELECT GROUP_CONCAT(JSON_ARRAY(c.COLUMN_NAME,c.COLUMN_TYPE,c.IS_NULLABLE,c.COLUMN_DEFAULT,c.EXTRA,c.GENERATION_EXPRESSION,c.CHARACTER_SET_NAME,c.COLLATION_NAME) ORDER BY c.ORDINAL_POSITION SEPARATOR '\n') FROM information_schema.COLUMNS c WHERE c.TABLE_SCHEMA=t.TABLE_SCHEMA AND c.TABLE_NAME=t.TABLE_NAME),  (SELECT GROUP_CONCAT(JSON_ARRAY(s.INDEX_NAME,s.NON_UNIQUE,s.SEQ_IN_INDEX,s.COLUMN_NAME,s.SUB_PART,s.INDEX_TYPE) ORDER BY s.INDEX_NAME,s.SEQ_IN_INDEX SEPARATOR '\n') FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA=t.TABLE_SCHEMA AND s.TABLE_NAME=t.TABLE_NAME),  (SELECT GROUP_CONCAT(JSON_ARRAY(k.CONSTRAINT_NAME,k.COLUMN_NAME,k.ORDINAL_POSITION,k.REFERENCED_TABLE_NAME,k.REFERENCED_COLUMN_NAME) ORDER BY k.CONSTRAINT_NAME,k.ORDINAL_POSITION SEPARATOR '\n') FROM information_schema.KEY_COLUMN_USAGE k WHERE k.TABLE_SCHEMA=t.TABLE_SCHEMA AND k.TABLE_NAME=t.TABLE_NAME),  (SELECT GROUP_CONCAT(JSON_ARRAY(r.CONSTRAINT_NAME,r.UPDATE_RULE,r.DELETE_RULE) ORDER BY r.CONSTRAINT_NAME SEPARATOR '\n') FROM information_schema.REFERENTIAL_CONSTRAINTS r WHERE r.CONSTRAINT_SCHEMA=t.TABLE_SCHEMA AND r.TABLE_NAME=t.TABLE_NAME),  (SELECT GROUP_CONCAT(JSON_ARRAY(ch.CONSTRAINT_NAME,ch.CHECK_CLAUSE) ORDER BY ch.CONSTRAINT_NAME SEPARATOR '\n') FROM information_schema.CHECK_CONSTRAINTS ch WHERE ch.CONSTRAINT_SCHEMA=t.TABLE_SCHEMA AND ch.TABLE_NAME=t.TABLE_NAME) )) AS signature FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA=DATABASE() AND t.TABLE_TYPE='BASE TABLE') actual ON actual.TABLE_NAME=expected.table_name WHERE actual.TABLE_NAME IS NULL OR actual.signature=expected.signature
SELECT 1;
